package com.formation.loan.model;
import jakarta.persistence.*; import java.time.LocalDate;
@Entity public class Loan { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String memberName; @Column(nullable=false) private Long bookId; @Column(nullable=false) private String bookTitle; private String bookAuthor; @Column(nullable=false) private String bookIsbn; @Column(nullable=false) private LocalDate loanDate; @Column(nullable=false) private LocalDate dueDate; private LocalDate returnDate; @Enumerated(EnumType.STRING) @Column(nullable=false) private LoanStatus status; @Column(nullable=false) private boolean deleted=false; protected Loan(){} public Loan(String memberName,Long bookId,String title,String author,String isbn,LocalDate date){this.memberName=memberName;this.bookId=bookId;this.bookTitle=title;this.bookAuthor=author;this.bookIsbn=isbn;this.loanDate=date;this.dueDate=date.plusDays(14);this.status=LoanStatus.ACTIVE;} public Long getId(){return id;} public String getMemberName(){return memberName;} public Long getBookId(){return bookId;} public String getBookTitle(){return bookTitle;} public String getBookAuthor(){return bookAuthor;} public String getBookIsbn(){return bookIsbn;} public LocalDate getLoanDate(){return loanDate;} public LocalDate getDueDate(){return dueDate;} public LocalDate getReturnDate(){return returnDate;} public LoanStatus getStatus(){return status;} public boolean isDeleted(){return deleted;} public void setDeleted(boolean v){deleted=v;} public void setStatus(LoanStatus s){status=s;} public void setReturnDate(LocalDate d){returnDate=d;} public void setBookTitle(String v){bookTitle=v;} public void setBookAuthor(String v){bookAuthor=v;} }
